const state={view:"dashboard",step:1,preview:"paper",paper:null,paperCount:0,questions:[]};
const $=(selector,root=document)=>root.querySelector(selector);
const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];

async function loadQuestions(){const response=await fetch("/api/questions");const data=await response.json();state.questions=data.items;renderQuestionBank();}

function switchView(view){state.view=view;$$('.view').forEach(el=>el.classList.remove('active-view'));$(`#${view}-view`).classList.add('active-view');$$('.nav-item').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#page-title').textContent=view==='dashboard'?'Good afternoon, Hari':view==='generator'?'Create question paper':view==='questions'?'Question bank':'Saved papers';if(view==='generator')updateWizard();}

function goGenerator(){switchView('generator');state.step=1;updateWizard();}

function selectedChapters(){return $$('.chapter-card input:checked').map(input=>input.value);}
function sections(){return $$('.section-count').map((input,index)=>({name:`Section ${String.fromCharCode(65+index)}`,type:input.dataset.type,marksPerQuestion:Number(input.dataset.marks),count:Number(input.value)}));}
function difficulty(){return {EASY:Number($('#easy').value),MEDIUM:Number($('#medium-diff').value),HARD:Number($('#hard').value)};}
function totalMarks(){return sections().reduce((sum,section)=>sum+section.count*section.marksPerQuestion,0);}
function totalQuestions(){return sections().reduce((sum,section)=>sum+section.count,0);}

function updateBlueprint(){$$('.blueprint-row:not(.header)').forEach(row=>{const input=$('input',row);$('b',row).textContent=Number(input.value)*Number(input.dataset.marks);});const marks=totalMarks();$('#total-marks').value=marks;$('#summary-marks').textContent=marks;$('#summary-questions').textContent=totalQuestions();const diff=difficulty();const diffTotal=diff.EASY+diff.MEDIUM+diff.HARD;$('#difficulty-total').textContent=`${diffTotal}%`;$$('.distribution input[type=range]').forEach(input=>input.nextElementSibling.value=`${input.value}%`);const valid=marks>0&&diffTotal===100&&selectedChapters().length>0;const box=$('#blueprint-validation');box.className=`validation-box ${valid?'valid':'invalid'}`;box.innerHTML=valid?`<strong>Blueprint valid</strong><p>${marks} marks across ${totalQuestions()} questions.</p>`:`<strong>Blueprint needs attention</strong><p>Difficulty must total 100% and at least one chapter is required.</p>`;$('#summary-status-text').textContent=valid?'Candidate pool will be checked during generation':'Correct the blueprint before continuing';return valid;}

function updateWizard(){$$('.wizard-step').forEach(panel=>panel.classList.toggle('active',Number(panel.dataset.panel)===state.step));$$('.step').forEach(step=>step.classList.toggle('active',Number(step.dataset.step)<=state.step));$('#back-step').style.visibility=state.step===1?'hidden':'visible';$('#next-step').textContent=state.step===1?'Continue':state.step===2?'Generate paper':'Finish';$('#summary-chapters').textContent=`${selectedChapters().length} selected`;$('#summary-name').textContent=$('#paper-name')?.value||'Class 10 Mathematics';updateBlueprint();}

async function generate(){const payload={name:$('#paper-name').value,institution:$('#institution').value,durationMinutes:Number($('#duration').value),chapters:selectedChapters(),difficulty:difficulty(),sections:sections()};const response=await fetch('/api/papers/generate',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!result.success){state.paper=null;$('#generation-error').classList.remove('hidden');$('#generation-error').innerHTML=`<strong>Unable to generate this blueprint.</strong><br>${result.deficits.map(d=>`${d.section}: requires ${d.required}, only ${d.available} available`).join('<br>')}`;$('#paper-preview').innerHTML='';return false;}$('#generation-error').classList.add('hidden');state.paper=result.paper;state.paperCount+=1;$('#paper-count').textContent=state.paperCount;renderPaper();addActivity(result.paper);return true;}

function renderPaper(){if(!state.paper)return;const p=state.paper;const container=$('#paper-preview');if(state.preview==='answers'){container.innerHTML=`<article class="paper-document"><header><h2>${escapeHtml(p.institution)}</h2><h2>Answer Key — ${escapeHtml(p.name)}</h2><p><span>${p.subject}</span><span>${p.totalMarks} marks</span></p></header>${p.questions.map((q,i)=>`<div class="answer"><strong>${i+1}. ${escapeHtml(q.answer)}</strong><p>${escapeHtml(q.solution)}</p></div>`).join('')}</article>`;return;}const grouped=Object.groupBy?Object.groupBy(p.questions,q=>q.section):p.questions.reduce((acc,q)=>((acc[q.section]??=[]).push(q),acc),{});container.innerHTML=`<article class="paper-document"><header><h2>${escapeHtml(p.institution)}</h2><h2>${escapeHtml(p.name)}</h2><p><span>${p.board} · ${p.standard} · ${p.subject}</span><span>Time: ${p.durationMinutes} min · Marks: ${p.totalMarks}</span></p></header><div class="instructions"><strong>Instructions:</strong> Answer all questions. Show all necessary working.</div>${Object.entries(grouped).map(([section,items])=>`<section class="paper-section"><h3>${section}</h3>${items.map((q,index)=>`<div class="paper-question"><strong>${index+1}.</strong> ${escapeHtml(q.text)} <b>[${q.marks}]</b>${q.options?`<div class="options">${q.options.map((o,i)=>`<span>${String.fromCharCode(65+i)}. ${escapeHtml(o)}</span>`).join('')}</div>`:''}</div>`).join('')}</section>`).join('')}</article>`;}

function addActivity(paper){const list=$('#activity-list');if(list.querySelector('.empty-inline'))list.innerHTML='';const item=document.createElement('div');item.className='activity';item.innerHTML=`<div><strong>${escapeHtml(paper.name)}</strong><span>${paper.totalMarks} marks · ${paper.questions.length} questions</span></div><span>Just now</span>`;list.prepend(item);}

function renderQuestionBank(query=''){const q=query.toLowerCase();const items=state.questions.filter(item=>item.text.toLowerCase().includes(q)||item.chapterName.toLowerCase().includes(q));$('#question-list').innerHTML=items.map(item=>`<article class="question-row"><div><p>${escapeHtml(item.text)}</p><div class="question-meta"><span class="tag">${item.chapterName}</span><span class="tag">${item.type.replaceAll('_',' ')}</span><span class="tag">${item.difficulty}</span><span class="tag">${item.source.replaceAll('_',' ')}</span></div></div><strong>${item.marks} mark${item.marks>1?'s':''}</strong></article>`).join('')||'<div class="empty-inline">No matching questions.</div>'; }
function escapeHtml(value){return String(value).replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]));}

$$('.nav-item').forEach(button=>button.addEventListener('click',()=>switchView(button.dataset.view)));['#new-paper','#hero-create','#saved-create'].forEach(id=>$(id).addEventListener('click',goGenerator));$('#back-step').addEventListener('click',()=>{if(state.step>1){state.step--;updateWizard();}});$('#next-step').addEventListener('click',async()=>{if(state.step===1&&selectedChapters().length===0)return alert('Select at least one chapter.');if(state.step===2&&!updateBlueprint())return;if(state.step===2){state.step=3;updateWizard();await generate();return;}if(state.step===3){switchView('dashboard');return;}state.step++;updateWizard();});$('#regenerate').addEventListener('click',generate);$('#print-paper').addEventListener('click',()=>window.print());$$('.segmented button').forEach(button=>button.addEventListener('click',()=>{state.preview=button.dataset.preview;$$('.segmented button').forEach(b=>b.classList.toggle('active',b===button));renderPaper();}));$$('.chapter-card input').forEach(input=>input.addEventListener('change',()=>{input.closest('.chapter-card').classList.toggle('selected',input.checked);updateWizard();}));$$('.section-count,.distribution input').forEach(input=>input.addEventListener('input',updateBlueprint));$('#paper-name').addEventListener('input',updateWizard);$('#question-search').addEventListener('input',event=>renderQuestionBank(event.target.value));$('.mobile-menu').addEventListener('click',()=>$('.sidebar').classList.toggle('open'));$('#language-toggle').addEventListener('click',event=>{event.target.textContent=event.target.textContent==='தமிழ்'?'English':'தமிழ்';});
loadQuestions();updateWizard();
